namespace Atm.Tests;

public class CashMachineTests
{
    private static readonly NoteCounts Full = new(5, 5, 5);

    private static AtmResult Withdraw(int balance, int withdrawn, NoteCounts stock, Denomination? jammed, int amount,
        out MoneyDispenser dispenser)
    {
        dispenser = new MoneyDispenser(stock, jammed);
        return new CashMachine(dispenser).Execute(new AccountState(balance, withdrawn), new Operation.Withdraw(amount));
    }

    private static AtmResult Deposit(int balance, int withdrawn, NoteCounts stock, Denomination? jammed, NoteCounts notes,
        out MoneyDispenser dispenser)
    {
        dispenser = new MoneyDispenser(stock, jammed);
        return new CashMachine(dispenser).Execute(new AccountState(balance, withdrawn), new Operation.Deposit(notes));
    }

    private static void AssertRefused(AtmResult result, AtmStatus status, AccountState account,
        MoneyDispenser dispenser, NoteCounts stock)
    {
        Assert.Equal(status, result.Status);
        Assert.Equal(NoteCounts.None, result.Notes);
        Assert.Equal(0, result.Fee);
        Assert.Equal(account, result.Account);
        Assert.Equal(stock, dispenser.Stock);
    }

    // ---- Exemples de la spécification ----

    [Fact]
    public void Example_Withdraw60_WithOnlyTwenties()
    {
        var stock = new NoteCounts(1, 3, 0);
        var result = Withdraw(100, 0, stock, null, 60, out var d);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new NoteCounts(0, 3, 0), 0, new AccountState(40, 60)), result);
        Assert.Equal(new NoteCounts(1, 0, 0), d.Stock);
    }

    [Fact]
    public void Example_Withdraw80_OneOfEach()
    {
        var result = Withdraw(100, 0, new NoteCounts(1, 1, 1), null, 80, out var d);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new NoteCounts(1, 1, 1), 0, new AccountState(20, 80)), result);
        Assert.Equal(NoteCounts.None, d.Stock);
    }

    [Fact]
    public void Example_Withdraw100_NoFee()
    {
        var result = Withdraw(105, 0, Full, null, 100, out _);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new NoteCounts(2, 0, 0), 0, new AccountState(5, 100)), result);
    }

    [Fact]
    public void Example_Withdraw110_WithFee()
    {
        var result = Withdraw(115, 0, Full, null, 110, out var d);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new NoteCounts(2, 0, 1), 5, new AccountState(0, 110)), result);
        Assert.Equal(new NoteCounts(3, 5, 4), d.Stock);
    }

    [Fact]
    public void Example_Withdraw110_FeeMakesFundsInsufficient()
    {
        var result = Withdraw(110, 0, Full, null, 110, out var d);
        AssertRefused(result, AtmStatus.InsufficientFunds, new AccountState(110, 0), d, Full);
    }

    [Fact]
    public void Example_DailyLimitExceeded()
    {
        var result = Withdraw(250, 150, Full, null, 60, out var d);
        AssertRefused(result, AtmStatus.DailyLimitExceeded, new AccountState(250, 150), d, Full);
    }

    [Fact]
    public void Example_JammedCassetteCountsAsZero_CannotDispense()
    {
        var stock = new NoteCounts(1, 0, 0);
        var result = Withdraw(250, 0, stock, Denomination.Fifty, 50, out var d);
        AssertRefused(result, AtmStatus.CannotDispense, new AccountState(250, 0), d, stock);
    }

    [Fact]
    public void Example_JammedFifties_UsesTwenties()
    {
        var result = Withdraw(250, 0, new NoteCounts(2, 2, 0), Denomination.Fifty, 40, out var d);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new NoteCounts(0, 2, 0), 0, new AccountState(210, 40)), result);
        Assert.Equal(new NoteCounts(2, 0, 0), d.Stock);
    }

    [Fact]
    public void Example_Withdraw5_InvalidAmount()
    {
        var result = Withdraw(0, 200, NoteCounts.None, null, 5, out var d);
        AssertRefused(result, AtmStatus.InvalidAmount, new AccountState(0, 200), d, NoteCounts.None);
    }

    [Fact]
    public void Example_Deposit_CassetteFull()
    {
        var stock = new NoteCounts(0, 5, 0);
        var result = Deposit(10, 0, stock, null, new NoteCounts(0, 1, 0), out var d);
        AssertRefused(result, AtmStatus.CassetteFull, new AccountState(10, 0), d, stock);
    }

    [Fact]
    public void Example_Deposit_CassetteJammed()
    {
        var stock = new NoteCounts(0, 1, 0);
        var result = Deposit(10, 30, stock, Denomination.Twenty, new NoteCounts(0, 1, 0), out var d);
        AssertRefused(result, AtmStatus.CassetteJammed, new AccountState(10, 30), d, stock);
    }

    [Fact]
    public void Example_Deposit_Ok()
    {
        var result = Deposit(10, 30, new NoteCounts(1, 1, 0), null, new NoteCounts(1, 0, 1), out var d);

        Assert.Equal(new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, new AccountState(70, 30)), result);
        Assert.Equal(new NoteCounts(2, 1, 1), d.Stock);
    }

    // ---- Retrait : contrôles ----

    [Theory]
    [InlineData(-10)]
    [InlineData(0)]
    [InlineData(5)]
    [InlineData(15)]
    public void Withdraw_InvalidAmount(int amount)
    {
        var result = Withdraw(250, 0, Full, null, amount, out var d);
        AssertRefused(result, AtmStatus.InvalidAmount, new AccountState(250, 0), d, Full);
    }

    [Fact]
    public void Withdraw_InvalidAmount_CheckedBeforeDailyLimit()
    {
        var result = Withdraw(0, 200, Full, null, -10, out _);
        Assert.Equal(AtmStatus.InvalidAmount, result.Status);
    }

    [Fact]
    public void Withdraw_DailyLimit_ReachedExactly_IsAllowed()
    {
        var result = Withdraw(250, 100, Full, null, 100, out _);

        Assert.Equal(AtmStatus.Ok, result.Status);
        Assert.Equal(new AccountState(150, 200), result.Account);
    }

    [Fact]
    public void Withdraw_DailyLimit_CheckedBeforeFunds()
    {
        var result = Withdraw(0, 0, Full, null, 210, out _);
        Assert.Equal(AtmStatus.DailyLimitExceeded, result.Status);
    }

    [Fact]
    public void Withdraw_FeeDoesNotCountTowardDailyLimit()
    {
        var result = Withdraw(250, 0, Full, null, 200, out _);

        Assert.Equal(AtmStatus.Ok, result.Status);
        Assert.Equal(5, result.Fee);
        Assert.Equal(new AccountState(45, 200), result.Account);
    }

    [Fact]
    public void Withdraw_FundsCheckedBeforeDispensability()
    {
        var result = Withdraw(10, 0, NoteCounts.None, null, 20, out _);
        Assert.Equal(AtmStatus.InsufficientFunds, result.Status);
    }

    [Fact]
    public void Withdraw_ExactBalance_IsAllowed()
    {
        var result = Withdraw(60, 0, Full, null, 60, out _);

        Assert.Equal(AtmStatus.Ok, result.Status);
        Assert.Equal(new AccountState(0, 60), result.Account);
    }

    [Theory]
    [InlineData(null)]
    [InlineData(Denomination.Twenty)]
    [InlineData(Denomination.Ten)]
    public void Withdraw_CannotDispense_WhenNoCombination(Denomination? jammed)
    {
        var stock = new NoteCounts(1, 0, 1);
        var result = Withdraw(250, 0, stock, jammed, 30, out var d);
        AssertRefused(result, AtmStatus.CannotDispense, new AccountState(250, 0), d, stock);
    }

    [Fact]
    public void Withdraw_JammedTens_IgnoresThem()
    {
        var result = Withdraw(250, 0, new NoteCounts(0, 3, 5), Denomination.Ten, 60, out var d);

        Assert.Equal(new NoteCounts(0, 3, 0), result.Notes);
        Assert.Equal(new NoteCounts(0, 0, 5), d.Stock);
    }

    [Fact]
    public void Withdraw_JammedTwenties_IgnoresThem()
    {
        var result = Withdraw(250, 0, new NoteCounts(1, 5, 2), Denomination.Twenty, 70, out var d);

        Assert.Equal(new NoteCounts(1, 0, 2), result.Notes);
        Assert.Equal(new NoteCounts(0, 5, 0), d.Stock);
    }

    [Fact]
    public void Withdraw_ChoosesFewestNotes_NotGreedy()
    {
        // Glouton : 50 puis bloqué sur 10 ; la seule solution est 20×3.
        var result = Withdraw(250, 0, new NoteCounts(1, 3, 0), null, 60, out _);
        Assert.Equal(new NoteCounts(0, 3, 0), result.Notes);
    }

    [Fact]
    public void Withdraw_ChoosesFewestNotes_AmongSeveral()
    {
        // 80 = 50+20+10 (3) plutôt que 20×4 (4) ou 50+10×3 (4).
        var result = Withdraw(250, 0, Full, null, 80, out _);
        Assert.Equal(new NoteCounts(1, 1, 1), result.Notes);
    }

    // ---- Retrait : passages ----

    [Fact]
    public void Withdraw_ManyNotes_SplitIntoPassesOfAtMostFour()
    {
        var fake = new RecordingDispenser(new NoteCounts(0, 5, 5));
        var result = new CashMachine(fake).Execute(new AccountState(250, 0), new Operation.Withdraw(150));

        Assert.Equal(AtmStatus.Ok, result.Status);
        Assert.Equal(new NoteCounts(0, 5, 5), result.Notes);
        Assert.Equal(new AccountState(95, 150), result.Account);
        Assert.All(fake.Passes, p => Assert.InRange(p.Total, 1, 4));
        Assert.Equal(3, fake.Passes.Count);
        Assert.Equal(new NoteCounts(0, 5, 5), fake.Passes.Aggregate(NoteCounts.None, (a, b) => a + b));
    }

    [Fact]
    public void Withdraw_WithRealDispenser_LargeWithdrawal()
    {
        var result = Withdraw(250, 0, new NoteCounts(1, 5, 5), null, 200, out var d);

        Assert.Equal(AtmStatus.Ok, result.Status);
        Assert.Equal(new NoteCounts(1, 5, 5), result.Notes);
        Assert.Equal(NoteCounts.None, d.Stock);
    }

    // ---- Pannes ----

    [Fact]
    public void Withdraw_FaultOnFirstPass_NoNotes()
    {
        var fake = new RecordingDispenser(Full) { FailDispenseOnPass = 1 };
        var account = new AccountState(250, 0);
        var result = new CashMachine(fake).Execute(account, new Operation.Withdraw(50));

        Assert.Equal(new AtmResult(AtmStatus.DispenserFault, NoteCounts.None, 0, account), result);
    }

    [Fact]
    public void Withdraw_FaultOnLaterPass_ReturnsAlreadyDispensedNotes()
    {
        var fake = new RecordingDispenser(new NoteCounts(0, 5, 5)) { FailDispenseOnPass = 2 };
        var account = new AccountState(250, 0);
        var result = new CashMachine(fake).Execute(account, new Operation.Withdraw(150));

        Assert.Equal(AtmStatus.DispenserFault, result.Status);
        Assert.Equal(0, result.Fee);
        Assert.Equal(account, result.Account);
        Assert.Equal(fake.Passes[0], result.Notes);
        Assert.Equal(4, result.Notes.Total);
        Assert.Equal(2, fake.Passes.Count);
    }

    [Fact]
    public void Deposit_Fault_NothingChanges()
    {
        var fake = new RecordingDispenser(NoteCounts.None) { FailLoad = true };
        var account = new AccountState(10, 30);
        var result = new CashMachine(fake).Execute(account, new Operation.Deposit(new NoteCounts(1, 1, 1)));

        Assert.Equal(new AtmResult(AtmStatus.DispenserFault, NoteCounts.None, 0, account), result);
    }

    // ---- Dépôt ----

    [Fact]
    public void Deposit_Empty_InvalidAmount()
    {
        var result = Deposit(10, 0, NoteCounts.None, Denomination.Ten, NoteCounts.None, out var d);
        AssertRefused(result, AtmStatus.InvalidAmount, new AccountState(10, 0), d, NoteCounts.None);
    }

    [Fact]
    public void Deposit_Jammed_CheckedBeforeFull()
    {
        var stock = new NoteCounts(5, 0, 0);
        var result = Deposit(10, 0, stock, Denomination.Fifty, new NoteCounts(1, 0, 0), out var d);
        AssertRefused(result, AtmStatus.CassetteJammed, new AccountState(10, 0), d, stock);
    }

    [Theory]
    [InlineData(5, 0, 0, 1, 0, 0)]
    [InlineData(0, 5, 0, 0, 1, 0)]
    [InlineData(0, 0, 5, 0, 0, 1)]
    [InlineData(0, 0, 5, 1, 1, 1)]
    public void Deposit_CassetteFull(int s50, int s20, int s10, int n50, int n20, int n10)
    {
        var stock = new NoteCounts(s50, s20, s10);
        var result = Deposit(10, 0, stock, null, new NoteCounts(n50, n20, n10), out var d);
        AssertRefused(result, AtmStatus.CassetteFull, new AccountState(10, 0), d, stock);
    }

    [Fact]
    public void Deposit_WithOtherCassetteJammed_IsAccepted()
    {
        var result = Deposit(0, 50, new NoteCounts(0, 0, 4), Denomination.Fifty, new NoteCounts(0, 1, 1), out var d);

        Assert.Equal(new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, new AccountState(30, 50)), result);
        Assert.Equal(new NoteCounts(0, 1, 5), d.Stock);
    }

    // ---- Divers ----

    [Fact]
    public void UnknownOperation_Throws()
    {
        var machine = new CashMachine(new MoneyDispenser(Full));
        Assert.Throws<ArgumentOutOfRangeException>(() => machine.Execute(new AccountState(0, 0), null!));
    }

    [Fact]
    public void Machine_IsStateless_BetweenCalls()
    {
        var dispenser = new MoneyDispenser(Full);
        var machine = new CashMachine(dispenser);
        var account = new AccountState(100, 0);

        var first = machine.Execute(account, new Operation.Withdraw(50));
        var second = machine.Execute(account, new Operation.Withdraw(50));

        Assert.Equal(first, second);
        Assert.Equal(new NoteCounts(3, 5, 5), dispenser.Stock);
    }

    // ---- Propriétés sur tout le domaine du stock ----

    public static IEnumerable<object?[]> StockDomain()
    {
        Denomination?[] jams = [null, Denomination.Fifty, Denomination.Twenty, Denomination.Ten];
        foreach (var jam in jams)
        {
            for (var f = 0; f <= 5; f++)
            for (var t = 0; t <= 5; t++)
            for (var c = 0; c <= 5; c++)
            {
                yield return [jam, f, t, c];
            }
        }
    }

    [Fact]
    public void Withdraw_AllStocks_MatchesBruteForceOracle()
    {
        foreach (var row in StockDomain())
        {
            var jam = (Denomination?)row[0];
            var stock = new NoteCounts((int)row[1]!, (int)row[2]!, (int)row[3]!);
            for (var amount = 10; amount <= 200; amount += 10)
            {
                var result = Withdraw(250, 0, stock, jam, amount, out var d);
                var expected = Oracle(amount, stock, jam);

                if (expected is { } notes)
                {
                    var fee = amount > 100 ? 5 : 0;
                    Assert.Equal(new AtmResult(AtmStatus.Ok, notes, fee, new AccountState(250 - amount - fee, amount)), result);
                    Assert.Equal(stock - notes, d.Stock);
                }
                else
                {
                    AssertRefused(result, AtmStatus.CannotDispense, new AccountState(250, 0), d, stock);
                }
            }
        }
    }

    private static NoteCounts? Oracle(int amount, NoteCounts stock, Denomination? jam)
    {
        NoteCounts? best = null;
        for (var f = 0; f <= 5; f++)
        for (var t = 0; t <= 5; t++)
        for (var c = 0; c <= 5; c++)
        {
            var n = new NoteCounts(f, t, c);
            var ok = n.Value == amount && f <= stock.Fifties && t <= stock.Twenties && c <= stock.Tens
                     && (jam is not { } j || n.Of(j) == 0);
            if (ok && (best is null || n.Total < best.Value.Total))
            {
                best = n;
            }
        }

        return best;
    }

    private sealed class RecordingDispenser(NoteCounts stock) : IMoneyDispenser
    {
        public NoteCounts Stock { get; private set; } = stock;
        public Denomination? Jammed => null;
        public List<NoteCounts> Passes { get; } = [];
        public int FailDispenseOnPass { get; init; }
        public bool FailLoad { get; init; }

        public bool Dispense(NoteCounts notes)
        {
            Passes.Add(notes);
            if (Passes.Count == FailDispenseOnPass || notes.Total is < 1 or > 4)
            {
                return false;
            }

            Stock -= notes;
            return true;
        }

        public bool Load(NoteCounts notes)
        {
            if (FailLoad)
            {
                return false;
            }

            Stock += notes;
            return true;
        }
    }
}
namespace Atm.Tests;

/// <summary>
/// Tests d'intégration : <see cref="CashMachine"/> travaille avec le vrai <see cref="MoneyDispenser"/>, sans doublure.
/// Après chaque opération, on vérifie le résultat rendu et le stock réellement présent dans le module.
/// </summary>
public class Integration
{
    private static readonly NoteCounts Full = new(5, 5, 5);
    private static readonly NoteCounts Empty = NoteCounts.None;

    private static readonly Denomination?[] Jams = [null, Denomination.Fifty, Denomination.Twenty, Denomination.Ten];

    private static readonly int[] Amounts = [-10, 0, 5, .. Enumerable.Range(1, 22).Select(i => i * 10)];

    // ======================================================================================================
    //  Outillage
    // ======================================================================================================

    /// <summary>Une machine et son vrai module, qui gardent leur état d'une opération à l'autre.</summary>
    private sealed class Guichet(NoteCounts stock, Denomination? jammed = null)
    {
        public MoneyDispenser Dispenser { get; } = new(stock, jammed);

        public CashMachine Machine => new(Dispenser);

        /// <summary>Exécute l'opération puis vérifie le résultat et le stock du module ; rend le compte après.</summary>
        public AccountState Step(AccountState account, Operation operation, AtmResult expected, NoteCounts expectedStock)
        {
            var result = Machine.Execute(account, operation);

            Assert.Equal(expected, result);
            Assert.Equal(expectedStock, Dispenser.Stock);
            Assert.Equal(jammed, Dispenser.Jammed);

            return result.Account;
        }

        public AccountState Ok(AccountState account, Operation operation, NoteCounts notes, int fee, AccountState after,
            NoteCounts expectedStock) =>
            Step(account, operation, new AtmResult(AtmStatus.Ok, notes, fee, after), expectedStock);

        /// <summary>Un refus : rien ne sort, aucun frais, compte et stock identiques.</summary>
        public AccountState Refused(AccountState account, Operation operation, AtmStatus status)
        {
            var before = Dispenser.Stock;
            return Step(account, operation, new AtmResult(status, Empty, 0, account), before);
        }
    }

    private static Operation W(int amount) => new Operation.Withdraw(amount);

    private static Operation D(int fifties, int twenties, int tens) => new Operation.Deposit(new NoteCounts(fifties, twenties, tens));

    private static NoteCounts N(int fifties, int twenties, int tens) => new(fifties, twenties, tens);

    private static AccountState A(int balance, int withdrawnToday) => new(balance, withdrawnToday);

    private static IEnumerable<NoteCounts> AllStocks()
    {
        for (var f = 0; f <= 5; f++)
        for (var t = 0; t <= 5; t++)
        for (var c = 0; c <= 5; c++)
        {
            yield return new NoteCounts(f, t, c);
        }
    }

    private static IEnumerable<NoteCounts> AllDeposits()
    {
        for (var f = 0; f <= 1; f++)
        for (var t = 0; t <= 1; t++)
        for (var c = 0; c <= 1; c++)
        {
            yield return new NoteCounts(f, t, c);
        }
    }

    private static IEnumerable<Operation> AllOperations() =>
        Amounts.Select(W).Concat(AllDeposits().Select(n => (Operation)new Operation.Deposit(n)));

    private static bool InDomain(AccountState account) =>
        account.Balance is >= 0 and <= 250 && account.Balance % 5 == 0
        && account.WithdrawnToday is >= 0 and <= 200 && account.WithdrawnToday % 10 == 0;

    /// <summary>
    /// Modèle de la spécification, écrit indépendamment de <see cref="CashMachine"/> : le résultat attendu et le stock
    /// du module après l'opération.
    /// </summary>
    private static (AtmResult Result, NoteCounts Stock) Expected(AccountState account, NoteCounts stock, Denomination? jam,
        Operation operation)
    {
        (AtmResult, NoteCounts) Refuse(AtmStatus status) => (new AtmResult(status, Empty, 0, account), stock);

        switch (operation)
        {
            case Operation.Withdraw { Amount: var amount }:
            {
                if (amount <= 0 || amount % 10 != 0) return Refuse(AtmStatus.InvalidAmount);
                if (account.WithdrawnToday + amount > 200) return Refuse(AtmStatus.DailyLimitExceeded);
                var fee = amount > 100 ? 5 : 0;
                if (amount + fee > account.Balance) return Refuse(AtmStatus.InsufficientFunds);
                if (FewestNotes(amount, stock, jam) is not { } notes) return Refuse(AtmStatus.CannotDispense);

                var after = new AccountState(account.Balance - amount - fee, account.WithdrawnToday + amount);
                return (new AtmResult(AtmStatus.Ok, notes, fee, after), stock - notes);
            }

            case Operation.Deposit { Notes: var notes }:
            {
                if (notes.Total == 0) return Refuse(AtmStatus.InvalidAmount);
                if (jam is { } j && notes.Of(j) > 0) return Refuse(AtmStatus.CassetteJammed);
                var after = stock + notes;
                if (after.Fifties > 5 || after.Twenties > 5 || after.Tens > 5) return Refuse(AtmStatus.CassetteFull);

                var account2 = account with { Balance = account.Balance + notes.Value };
                return (new AtmResult(AtmStatus.Ok, Empty, 0, account2), after);
            }

            default:
                throw new ArgumentOutOfRangeException(nameof(operation));
        }
    }

    /// <summary>La combinaison exacte qui compte le moins de billets parmi les billets disponibles (unique d'après la spec).</summary>
    private static NoteCounts? FewestNotes(int amount, NoteCounts stock, Denomination? jam)
    {
        var available = jam switch
        {
            Denomination.Fifty => stock with { Fifties = 0 },
            Denomination.Twenty => stock with { Twenties = 0 },
            Denomination.Ten => stock with { Tens = 0 },
            _ => stock,
        };

        var candidates = new List<NoteCounts>();
        for (var f = 0; f <= available.Fifties; f++)
        for (var t = 0; t <= available.Twenties; t++)
        for (var c = 0; c <= available.Tens; c++)
        {
            if (f * 50 + t * 20 + c * 10 == amount)
            {
                candidates.Add(new NoteCounts(f, t, c));
            }
        }

        if (candidates.Count == 0)
        {
            return null;
        }

        var min = candidates.Min(n => n.Total);
        var best = candidates.Where(n => n.Total == min).ToList();
        Assert.Single(best); // la spec affirme l'unicité : on le vérifie au passage

        return best[0];
    }

    private static string Describe(AccountState account, NoteCounts stock, Denomination? jam, Operation operation) =>
        $"compte {account}, stock {stock}, bloquée {jam?.ToString() ?? "aucune"}, opération {operation}";

    /// <summary>Exécute une opération sur le vrai module et la compare au modèle ; rend le compte après.</summary>
    private static AccountState CheckAgainstModel(MoneyDispenser dispenser, AccountState account, Operation operation,
        string history = "")
    {
        var stock = dispenser.Stock;
        var (expected, expectedStock) = Expected(account, stock, dispenser.Jammed, operation);

        var result = new CashMachine(dispenser).Execute(account, operation);

        if (result != expected || dispenser.Stock != expectedStock)
        {
            Assert.Fail($"{history}{Describe(account, stock, dispenser.Jammed, operation)}\n"
                        + $"  attendu : {expected}, stock {expectedStock}\n"
                        + $"  obtenu  : {result}, stock {dispenser.Stock}");
        }

        return result.Account;
    }

    // ======================================================================================================
    //  Scénarios : plusieurs opérations à la suite sur le même module
    // ======================================================================================================

    [Fact]
    public void Scenario_DayOfOneCustomer_WithdrawalsDailyLimitThenDeposits()
    {
        var atm = new Guichet(Full);
        var account = A(250, 0);

        account = atm.Ok(account, W(80), N(1, 1, 1), 0, A(170, 80), N(4, 4, 4));
        account = atm.Refused(account, W(130), AtmStatus.DailyLimitExceeded);         // 80 + 130 > 200
        account = atm.Ok(account, W(120), N(2, 1, 0), 5, A(45, 200), N(2, 3, 4));     // frais, plafond atteint pile
        account = atm.Refused(account, W(10), AtmStatus.DailyLimitExceeded);
        account = atm.Ok(account, D(1, 1, 1), Empty, 0, A(125, 200), N(3, 4, 5));     // le dépôt ne touche pas au plafond
        account = atm.Refused(account, D(0, 0, 1), AtmStatus.CassetteFull);
        account = atm.Ok(account, D(1, 1, 0), Empty, 0, A(195, 200), N(4, 5, 5));
        atm.Refused(account, D(0, 1, 0), AtmStatus.CassetteFull);
    }

    [Fact]
    public void Scenario_SeveralCustomers_DrainTheModule_ThenADepositRefillsIt()
    {
        var atm = new Guichet(N(1, 2, 3));

        // Premier client : 100 = 50 + 20×2 + 10, la combinaison la plus courte.
        atm.Ok(A(250, 0), W(100), N(1, 2, 1), 0, A(150, 100), N(0, 0, 2));

        // Second client : le stock laissé par le premier ne permet plus que 10 ou 20.
        var account = A(100, 0);
        account = atm.Refused(account, W(30), AtmStatus.CannotDispense);
        account = atm.Ok(account, W(20), N(0, 0, 2), 0, A(80, 20), Empty);
        account = atm.Refused(account, W(10), AtmStatus.CannotDispense);
        account = atm.Ok(account, D(1, 1, 1), Empty, 0, A(160, 20), N(1, 1, 1));
        account = atm.Ok(account, W(80), N(1, 1, 1), 0, A(80, 100), Empty);
        atm.Refused(account, W(50), AtmStatus.CannotDispense);
    }

    [Fact]
    public void Scenario_JammedTwenties_StayUntouchedForTheWholeSession()
    {
        var atm = new Guichet(N(3, 3, 3), Denomination.Twenty);
        var account = A(100, 0);

        account = atm.Refused(account, D(0, 1, 0), AtmStatus.CassetteJammed);
        account = atm.Refused(account, D(1, 1, 1), AtmStatus.CassetteJammed);
        account = atm.Ok(account, D(1, 0, 1), Empty, 0, A(160, 0), N(4, 3, 4));
        account = atm.Ok(account, W(60), N(1, 0, 1), 0, A(100, 60), N(3, 3, 3));
        account = atm.Refused(account, W(40), AtmStatus.CannotDispense);              // 20×2 dans la cassette bloquée, 10×3 seulement
        account = atm.Ok(account, W(30), N(0, 0, 3), 0, A(70, 90), N(3, 3, 0));
        account = atm.Refused(account, W(20), AtmStatus.CannotDispense);
        account = atm.Ok(account, W(50), N(1, 0, 0), 0, A(20, 140), N(2, 3, 0));
        atm.Refused(account, W(20), AtmStatus.CannotDispense);                         // fonds suffisants, mais 20 bloqués

        Assert.Equal(3, atm.Dispenser.Stock.Twenties);
    }

    [Theory]
    [InlineData(Denomination.Fifty)]
    [InlineData(Denomination.Twenty)]
    [InlineData(Denomination.Ten)]
    public void Scenario_JammedCassette_NeverChanges_WhateverTheOperations(Denomination jam)
    {
        var dispenser = new MoneyDispenser(N(2, 2, 2), jam);
        var jammedCount = dispenser.Stock.Of(jam);
        var account = A(100, 0);

        foreach (var operation in AllOperations())
        {
            account = CheckAgainstModel(dispenser, account, operation);
            Assert.Equal(jammedCount, dispenser.Stock.Of(jam));
            if (!InDomain(account))
            {
                account = A(100, 0);
            }
        }
    }

    [Fact]
    public void Scenario_WithdrawalNeedingSeveralPasses_ThenRefillCassetteByCassette()
    {
        // Dix billets : le vrai module refuse plus de 4 billets par passage, la machine doit découper.
        var atm = new Guichet(N(0, 5, 5));
        var account = atm.Ok(A(250, 0), W(150), N(0, 5, 5), 5, A(95, 150), Empty);

        for (var i = 1; i <= 5; i++)
        {
            account = atm.Ok(account, D(0, 1, 1), Empty, 0, A(95 + 30 * i, 150), N(0, i, i));
        }

        account = atm.Refused(account, D(0, 1, 0), AtmStatus.CassetteFull);
        account = atm.Refused(account, D(0, 0, 1), AtmStatus.CassetteFull);
        atm.Ok(account, D(1, 0, 0), Empty, 0, A(295, 150), N(1, 5, 5));
    }

    [Fact]
    public void Scenario_LargestWithdrawal_ElevenNotesInThreePasses_EmptiesTheModule()
    {
        var atm = new Guichet(N(1, 5, 5));
        var account = atm.Ok(A(205, 0), W(200), N(1, 5, 5), 5, A(0, 200), Empty);

        atm.Refused(account, W(10), AtmStatus.DailyLimitExceeded);
        atm.Refused(A(250, 0), W(10), AtmStatus.CannotDispense);
    }

    [Fact]
    public void Scenario_FullCassette_FreedByAWithdrawal_AcceptsTheDepositAgain()
    {
        var atm = new Guichet(N(5, 0, 0));
        var account = A(60, 0);

        account = atm.Refused(account, D(1, 0, 0), AtmStatus.CassetteFull);
        account = atm.Ok(account, W(50), N(1, 0, 0), 0, A(10, 50), N(4, 0, 0));
        account = atm.Ok(account, D(1, 0, 0), Empty, 0, A(60, 50), N(5, 0, 0));
        atm.Refused(account, D(1, 0, 0), AtmStatus.CassetteFull);
    }

    [Fact]
    public void Scenario_EmptyCassette_FilledByADeposit_MakesTheAmountDispensable()
    {
        var atm = new Guichet(Empty);
        var account = A(100, 0);

        account = atm.Refused(account, W(70), AtmStatus.CannotDispense);
        account = atm.Ok(account, D(1, 1, 0), Empty, 0, A(170, 0), N(1, 1, 0));
        account = atm.Ok(account, W(70), N(1, 1, 0), 0, A(100, 70), Empty);
        atm.Refused(account, W(70), AtmStatus.CannotDispense);
    }

    [Fact]
    public void Scenario_RefusalsInTheMiddle_DoNotDisturbTheFollowingOperations()
    {
        var atm = new Guichet(N(2, 2, 2));
        var account = A(200, 100);

        account = atm.Refused(account, W(-10), AtmStatus.InvalidAmount);
        account = atm.Refused(account, W(0), AtmStatus.InvalidAmount);
        account = atm.Refused(account, W(5), AtmStatus.InvalidAmount);
